// A programmable four-bit pattern detector.
//
// The pattern is an input, not a constant, so there is no table to
// precompute: the last four bits are kept in a shift register and
// compared with it. `fill` is there to stop the register matching
// before four real bits have arrived.

module seq_match (
    input  logic       clk,
    input  logic       rst_n,     // synchronous, active low
    input  logic       din,       // one bit per clock
    input  logic [3:0] pattern,   // held steady; pattern[3] arrives first
    output logic       found      // registered: high for one cycle on a match
);

    logic [3:0] hist;    // the last four bits; hist[3] is the oldest
    logic [2:0] fill;    // bits received since reset, saturating at 4

    // What the shift register will hold after this edge.
    wire [3:0] next_hist = {hist[2:0], din};

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            hist  <= 4'b0;
            fill  <= 3'd0;
            found <= 1'b0;
        end else begin
            hist  <= next_hist;
            if (fill != 3'd4) fill <= fill + 3'd1;
            // Three bits already in, plus the one arriving now.
            found <= (fill >= 3'd3) && (next_hist == pattern);
        end
    end

endmodule

// A saturating counter: it counts `inc` pulses and stops at its
// maximum rather than wrapping round to zero.

module det_counter #(
    parameter int W = 4
) (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         inc,
    output logic [W-1:0] count,
    output logic         sat
);

    // Saturated when every bit is set: one more pulse changes nothing.
    assign sat = &count;

    always_ff @(posedge clk) begin
        if (!rst_n)           count <= '0;
        else if (inc && !sat) count <= count + 1'b1;
    end

endmodule

// A one-shot arming gate.
//
// The gate holds one bit of state. A detection arriving while the gate
// is armed is passed on, and shuts the gate behind it. A detection
// arriving while the gate is shut is reported as missed instead.

module arm_gate (
    input  logic clk,
    input  logic rst_n,       // synchronous, active low
    input  logic arm,         // a one-cycle pulse: arms the gate
    input  logic found_in,
    output logic found_out,   // found_in, while armed
    output logic missed       // found_in, while not armed
);

    // your code here.
    //
    // Both outputs are combinational: this cycle's found_in against
    // this cycle's armed state, not a cycle later.
    //
    // The state register has three cases, and the ORDER of them is the
    // specification: reset wins over everything, then `arm`, and only
    // then the self-disarm. So an arm pulse landing on the same cycle
    // as a passed detection leaves the gate armed.

    assign found_out = 1'b0;
    assign missed    = 1'b0;

endmodule

// The top of milestone 3: the detector, the gate, and two counters.
//
// Note the port list: it has grown since milestone 2. If you carried
// your own version of this file forward it will not have `arm`,
// `missed` or `missed_count` on it, and the testbench will not
// elaborate until they are there.
//
// Still no logic of its own. det_counter is instantiated twice, which
// is the reason it was made a module in the first place.

module seq_detect #(
    parameter int W = 4
) (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         din,
    input  logic [3:0]   pattern,
    input  logic         arm,
    output logic         found,          // the gated detection
    output logic         missed,
    output logic [W-1:0] count,
    output logic [W-1:0] missed_count,
    output logic         sat             // the passed counter's saturation
);

    // your code here -- seq_match, then arm_gate, then two
    // det_counters. The raw detection goes into the gate, not straight
    // into a counter.

    assign found        = 1'b0;
    assign missed       = 1'b0;
    assign count        = '0;
    assign missed_count = '0;
    assign sat          = 1'b0;

endmodule

payload.testbench:
`timescale 1ns/1ps

// The sample testbench for milestone 3. Submit uses another one, which
// presses on the priority rule and on both counters.
module tb;

  localparam int W = 4;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst_n = 1'b1;
  logic din   = 1'b0;
  logic arm   = 1'b0;
  logic found, missed;
  logic [W-1:0] count, missed_count;
  logic sat;

  logic [3:0] pattern = 4'b1011;

  seq_detect #(.W(W)) dut (
    .clk(clk), .rst_n(rst_n), .din(din), .pattern(pattern), .arm(arm),
    .found(found), .missed(missed),
    .count(count), .missed_count(missed_count), .sat(sat)
  );

  integer i;

  // One cycle, driving both inputs, so that "arm on the same cycle as
  // the detection" is a thing the testbench can actually express.
  task tick(input logic b, input logic a);
    begin
      @(negedge clk); din = b; arm = a;
      @(posedge clk); #1;
    end
  endtask

  task send(input logic b);
    begin
      tick(b, 1'b0);
    end
  endtask

  task arm_cycle;
    begin
      tick(1'b0, 1'b1);
    end
  endtask

  task reset;
    begin
      @(negedge clk); rst_n = 1'b0; din = 1'b0; arm = 1'b0;
      @(posedge clk); #1;
      rst_n = 1'b1;
    end
  endtask

  task stream(input integer n, input [31:0] bits);
    begin
      for (i = n - 1; i >= 0; i = i - 1) send(bits[i]);
    end
  endtask

  logic [W-1:0] c_shut, m_shut, c_armed, m_armed;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    // Shut: the pattern is still detected, and reported as missed.
    reset();
    stream(4, 4'b1011);
    send(1'b0);
    c_shut = count;
    m_shut = missed_count;

    // Armed: the first match gets through and the gate shuts behind it.
    reset();
    arm_cycle();
    stream(7, 7'b1011011);
    send(1'b0);
    c_armed = count;
    m_armed = missed_count;

    $display("CHECK shut_passes_nothing 0 %0d AT %0d", c_shut, $time);
    $display("CHECK shut_counts_as_missed 1 %0d AT %0d", m_shut, $time);
    $display("CHECK armed_passes_one 1 %0d AT %0d", c_armed, $time);
    $display("CHECK and_the_second_is_missed 1 %0d AT %0d", m_armed, $time);
    $display("DONE 4");
    $finish;
  end

endmodule
